const defaults={pickup:'TG Factory #4',shipping:{'Phnom Penh':'$2.00','Other provinces':'$3.50','Remote areas':'$5.00'},hero_en:'A little light, for every day.',hero_km:'សម្រស់តិចៗ សម្រាប់រាល់ថ្ងៃ។',hero_text_en:'Curated clothing and bags. Prices are in USD. Delivery or pickup available.',hero_text_km:'សម្លៀកបំពាក់ និងកាបូបដែលបានជ្រើសរើស។ តម្លៃគិតជា USD។ មានដឹកជញ្ជូន ឬមកយកផ្ទាល់។'};
const state={view:'shop',category:'all',language:localStorage.getItem('cypress-language')||'en',cart:JSON.parse(localStorage.getItem('cypress-cart')||'[]'),delivery:'delivery',region:'Phnom Penh',settings:defaults,products:[],orders:[],adminTab:'products'};
const copy={en:{shop:'Shop',admin:'Admin',heroTag:'CYPRESS FASHION STORE',new:'New arrival',featured:'Featured this week',items:'items',all:'All',clothes:'Clothing',bags:'Bags',add:'Add to bag',bag:'Bag',continue:'← Continue shopping',yourOrder:'Your order',empty:'Your shopping bag is empty.',name:'Full name',contact:'Telegram / phone number',delivery:'Delivery',deliveryHint:'Shipping is calculated by area',pickup:'Pickup',region:'Delivery area',address:'Full address',addressHint:'Province / district / street / house',total:'Total',requestQR:'Request payment QR',paymentHint:'The bot will send your payment QR and order number in Telegram. Payment is confirmed manually.',pickupNotice:'Pickup location:',adminTitle:'Store management',products:'Products',orders:'Orders',settings:'Home & delivery',upload:'Add product',save:'Save',delete:'Delete',edit:'Edit',price:'Price (USD)',photo:'Product photo',productEn:'Product name (English)',productKm:'Product name (Khmer)',descriptionEn:'Description (English)',descriptionKm:'Description (Khmer)',published:'Show in shop',featuredItem:'Featured',adminKey:'Enter admin key',saved:'Saved.',orderSent:'Order requested. Check your Telegram chat for the payment QR.',serverError:'Could not connect to the store server.',noProducts:'No products yet. The owner will add products soon.',homeTitle:'Home page text',pickupAddress:'Pickup address',shippingFees:'Delivery fees (USD)',status:'Status',customer:'Customer',order:'Order',date:'Date',footer:'Cypress Fashion Store · USD · Telegram Mini App'},km:{shop:'ហាង',admin:'គ្រប់គ្រង',heroTag:'ហាងម៉ូដ CYPRESS',new:'ទំនិញថ្មី',featured:'ជម្រើសប្រចាំសប្ដាហ៍',items:'មុខទំនិញ',all:'ទាំងអស់',clothes:'សម្លៀកបំពាក់',bags:'កាបូប',add:'បន្ថែមទៅកាបូប',bag:'កាបូប',continue:'← បន្តការទិញ',yourOrder:'ការបញ្ជាទិញរបស់អ្នក',empty:'កាបូបរបស់អ្នកនៅទទេ។',name:'ឈ្មោះពេញ',contact:'Telegram / លេខទូរស័ព្ទ',delivery:'ដឹកជញ្ជូន',deliveryHint:'ថ្លៃដឹកគិតតាមតំបន់',pickup:'មកយកផ្ទាល់',region:'តំបន់ដឹកជញ្ជូន',address:'អាសយដ្ឋានពេញលេញ',addressHint:'ខេត្ត / ស្រុក / ផ្លូវ / ផ្ទះ',total:'សរុប',requestQR:'ស្នើ QR កូដបង់ប្រាក់',paymentHint:'បូតនឹងផ្ញើ QR កូដបង់ប្រាក់ និងលេខបញ្ជាទិញតាម Telegram។ ការបង់ប្រាក់ត្រូវបានបញ្ជាក់ដោយដៃ។',pickupNotice:'ទីតាំងមកយក:',adminTitle:'ការគ្រប់គ្រងហាង',products:'ផលិតផល',orders:'ការបញ្ជាទិញ',settings:'ទំព័រដើម និងដឹកជញ្ជូន',upload:'បន្ថែមផលិតផល',save:'រក្សាទុក',delete:'លុប',edit:'កែប្រែ',price:'តម្លៃ (USD)',photo:'រូបភាពផលិតផល',productEn:'ឈ្មោះផលិតផល (អង់គ្លេស)',productKm:'ឈ្មោះផលិតផល (ខ្មែរ)',descriptionEn:'ការពិពណ៌នា (អង់គ្លេស)',descriptionKm:'ការពិពណ៌នា (ខ្មែរ)',published:'បង្ហាញក្នុងហាង',featuredItem:'ជម្រើសពិសេស',adminKey:'បញ្ចូលសោគ្រប់គ្រង',saved:'បានរក្សាទុក។',orderSent:'បានស្នើការបញ្ជាទិញ។ សូមពិនិត្យ Telegram របស់អ្នកសម្រាប់ QR កូដបង់ប្រាក់។',serverError:'មិនអាចភ្ជាប់ Server ហាងបានទេ។',noProducts:'មិនទាន់មានផលិតផលទេ។ ម្ចាស់ហាងនឹងបន្ថែមឆាប់ៗនេះ។',homeTitle:'អត្ថបទទំព័រដើម',pickupAddress:'អាសយដ្ឋានមកយក',shippingFees:'ថ្លៃដឹកជញ្ជូន (USD)',status:'ស្ថានភាព',customer:'អតិថិជន',order:'ការបញ្ជាទិញ',date:'កាលបរិច្ឆេទ',footer:'ហាងម៉ូដ Cypress · USD · Telegram Mini App'}};
const $=s=>document.querySelector(s),t=k=>copy[state.language][k]||copy.en[k]||k,money=n=>`$${Number(n||0).toFixed(2)}`;
function save(){localStorage.setItem('cypress-cart',JSON.stringify(state.cart));localStorage.setItem('cypress-language',state.language)}
function image(p){return p.image_url?`<img src="${p.image_url}" alt="${p.name_en}">`:`<div class="blank-image">${t(p.category)}</div>`}
function productName(p){return state.language==='km'&&p.name_km?p.name_km:p.name_en}function description(p){return state.language==='km'&&p.description_km?p.description_km:p.description_en}
function header(){return `<header class="topbar"><div class="brand">CYPRESS<span>Fashion Store</span></div><div class="top-actions"><button class="pill" onclick="setLanguage()">${state.language==='en'?'ខ្មែរ':'EN'}</button><button class="pill ${state.view==='shop'?'active':''}" onclick="showShop()">${t('shop')}</button><button class="pill ${state.view==='admin'?'active':''}" onclick="showAdmin()">${t('admin')}</button></div></header>`}
function render(){$('#app').innerHTML=`<main class="shell">${header()}${state.view==='shop'?shop():state.view==='cart'?cart():admin()}<footer class="footer">${t('footer')}</footer></main>`}
function shop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section><div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products">${list.length?list.map(p=>`<article class="product"><div class="product-image">${image(p)}</div><div class="product-body"><h3 class="product-title">${productName(p)}</h3><p class="description">${description(p)}</p><div class="product-meta"><span>${t(p.category)}</span><span class="product-price">${money(p.price)}</span></div><button class="add" onclick="add('${p.id}')">${t('add')}</button></div></article>`).join(''):`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
function cart(){const rows=state.cart.map(i=>{const p=state.products.find(x=>x.id===i.id);if(!p)return '';return `<div class="cart-row"><div class="thumb">${image(p)}</div><div><p>${productName(p)}</p><div class="quantity"><button onclick="change('${p.id}',-1)">−</button> ${i.qty} <button onclick="change('${p.id}',1)">+</button></div></div><div class="right"><b>${money(p.price*i.qty)}</b><br><button class="back" onclick="removeItem('${p.id}')">×</button></div></div>`}).join(''),sub=state.cart.reduce((n,i)=>n+(state.products.find(p=>p.id===i.id)?.price||0)*i.qty,0);return `<section class="panel"><button class="back" onclick="showShop()">${t('continue')}</button><h2>${t('yourOrder')}</h2>${rows||`<div class="empty">${t('empty')}</div>`}${state.cart.length?checkout(sub):''}</section>`}
function checkout(sub){const regions=Object.keys(state.settings.shipping||{});if(!regions.includes(state.region))state.region=regions[0]||'';const shipping=state.delivery==='delivery'?Number(String(state.settings.shipping[state.region]||'$0').replace('$','')):0;return `<div class="form-grid"><label class="field">${t('name')}<input id="customer-name"></label><label class="field">${t('contact')}<input id="customer-contact" placeholder="@username or 012…"></label></div><div class="delivery"><button class="${state.delivery==='delivery'?'selected':''}" onclick="delivery('delivery')"><b>${t('delivery')}</b><br><small>${t('deliveryHint')}</small></button><button class="${state.delivery==='pickup'?'selected':''}" onclick="delivery('pickup')"><b>${t('pickup')}</b><br><small>${state.settings.pickup}</small></button></div>${state.delivery==='delivery'?`<label class="field">${t('region')}<select onchange="region(this.value)">${regions.map(k=>`<option ${k===state.region?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">${t('address')}<textarea id="customer-address" placeholder="${t('addressHint')}"></textarea></label>`:`<div class="notice">${t('pickupNotice')} ${state.settings.pickup}</div>`}<div class="checkout-total"><span>${t('total')}</span><span>${money(sub+shipping)}</span></div><button class="primary" onclick="requestQR()">${t('requestQR')}</button><p class="footer">${t('paymentHint')}</p>`}
function admin(){return `<section><div class="section-head"><h2>${t('adminTitle')}</h2></div><div class="admin-nav">${['products','orders','settings'].map(x=>`<button class="${state.adminTab===x?'selected':''}" onclick="adminTab('${x}')">${t(x)}</button>`).join('')}</div>${state.adminTab==='products'?productAdmin():state.adminTab==='orders'?ordersAdmin():settingsAdmin()}</section>`}
function productAdmin(){return `<div class="admin-grid"><div class="panel"><h2>${t('upload')}</h2><form id="product-form" onsubmit="saveProduct(event)"><div class="form-grid"><label class="field">${t('productEn')}<input name="name_en" required></label><label class="field">${t('productKm')}<input name="name_km"></label></div><div class="form-grid"><label class="field">${t('price')}<input name="price" type="number" step="0.01" min="0" required></label><label class="field">${t('category')}<select name="category"><option value="clothes">${t('clothes')}</option><option value="bags">${t('bags')}</option></select></label></div><label class="field">${t('descriptionEn')}<textarea name="description_en"></textarea></label><label class="field">${t('descriptionKm')}<textarea name="description_km"></textarea></label><label class="field">${t('photo')}<input name="photo" type="file" accept="image/png,image/jpeg,image/webp" required></label><div class="checks"><label><input name="published" type="checkbox" checked> ${t('published')}</label><label><input name="featured" type="checkbox"> ${t('featuredItem')}</label></div><button class="primary">${t('save')}</button></form></div><div class="panel"><h2>${t('products')}</h2><div class="admin-products">${state.products.map(p=>`<div class="admin-product"><div class="mini">${image(p)}</div><div><b>${p.name_en}</b><br><small>${money(p.price)} · ${p.published?t('published'):'Hidden'}</small></div><button class="danger" onclick="deleteProduct('${p.id}')">${t('delete')}</button></div>`).join('')||`<div class="empty">${t('noProducts')}</div>`}</div></div></div>`}
function ordersAdmin(){return `<div class="panel"><h2>${t('orders')}</h2><table class="orders"><tr><th>${t('order')}</th><th>${t('customer')}</th><th>${t('total')}</th><th>${t('status')}</th></tr>${state.orders.map(o=>`<tr><td>${o.order_number}<br><small>${new Date(o.created_at).toLocaleDateString()}</small></td><td>${o.customer_name}<br><small>${o.contact}</small></td><td>${money(o.total)}</td><td><select onchange="setOrderStatus('${o.id}',this.value)">${['awaiting_payment','paid','shipping','ready_for_pickup','completed','cancelled'].map(s=>`<option value="${s}" ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')||`<tr><td colspan="4">${t('empty')}</td></tr>`}</table></div>`}
function settingsAdmin(){const fees=Object.entries(state.settings.shipping||{}).map(([k,v])=>`<div class="settings-row"><span>${k}</span><label>$ <input name="fee-${k}" value="${String(v).replace('$','')}"></label></div>`).join('');return `<div class="panel"><h2>${t('homeTitle')}</h2><form id="settings-form" onsubmit="saveSettings(event)"><label class="field">English headline<input name="hero_en" value="${state.settings.hero_en||''}"></label><label class="field">Khmer headline<input name="hero_km" value="${state.settings.hero_km||''}"></label><label class="field">English introduction<textarea name="hero_text_en">${state.settings.hero_text_en||''}</textarea></label><label class="field">Khmer introduction<textarea name="hero_text_km">${state.settings.hero_text_km||''}</textarea></label><label class="field">${t('pickupAddress')}<input name="pickup" value="${state.settings.pickup||''}"></label><h3>${t('shippingFees')}</h3>${fees}<button class="primary">${t('save')}</button></form></div>`}
function add(id){const x=state.cart.find(x=>x.id===id);x?x.qty++:state.cart.push({id,qty:1});save();render()}function setCategory(x){state.category=x;render()}function setLanguage(){state.language=state.language==='en'?'km':'en';save();render()}function showCart(){state.view='cart';render()}function showShop(){state.view='shop';render()}async function showAdmin(){state.view='admin';await loadAdmin();render()}function adminTab(x){state.adminTab=x;render()}function change(id,n){const x=state.cart.find(x=>x.id===id);x.qty+=n;if(x.qty<1)state.cart=state.cart.filter(y=>y!==x);save();render()}function removeItem(id){state.cart=state.cart.filter(x=>x.id!==id);save();render()}function delivery(x){state.delivery=x;render()}function region(x){state.region=x;render()}
function key(){const input=$('#admin-key')?.value.trim();if(input)state.adminKey=input;return state.adminKey||''}async function adminFetch(url,options={}){const k=key();if(!k)throw Error('Enter the admin key above.');const res=await fetch(url,{...options,headers:{'content-type':'application/json','x-admin-key':k,...(options.headers||{})}});if(!res.ok)throw Error((await res.json().catch(()=>({}))).error||'Request failed');return res.status===204?null:res.json()}
async function loadStore(){try{const response=await fetch('/api/store');if(!response.ok)throw Error('Store data unavailable');const data=await response.json();state.settings=data.settings||defaults;state.products=Array.isArray(data.products)?data.products:[];state.cart=state.cart.filter(i=>state.products.some(p=>p.id===i.id));}catch{state.settings=defaults;state.products=[];alert(t('serverError'))}render()}async function loadAdmin(){try{const data=await adminFetch('/api/admin/store');state.settings=data.settings||defaults;state.products=Array.isArray(data.products)?data.products:[];state.orders=Array.isArray(data.orders)?data.orders:[];}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
async function saveProduct(event){event.preventDefault();const form=event.currentTarget,file=form.photo.files[0];if(!file)return;const imageData=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const input=Object.fromEntries(new FormData(form));input.imageData=imageData;input.published=form.published.checked;input.featured=form.featured.checked;try{await adminFetch('/api/admin/products',{method:'POST',body:JSON.stringify(input)});form.reset();await loadAdmin();render();alert(t('saved'))}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
async function deleteProduct(id){if(!confirm('Delete this product?'))return;try{await adminFetch(`/api/admin/products/${id}`,{method:'DELETE'});await loadAdmin();render()}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
async function setOrderStatus(id,status){try{await adminFetch(`/api/admin/orders/${id}`,{method:'PATCH',body:JSON.stringify({status})});await loadAdmin()}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
async function saveSettings(event){event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form));data.shipping={};Object.keys(state.settings.shipping||{}).forEach(k=>{data.shipping[k]='$'+Number(data[`fee-${k}`]||0).toFixed(2);delete data[`fee-${k}`]});try{await adminFetch('/api/admin/settings',{method:'PUT',body:JSON.stringify(data)});state.settings=data;render();alert(t('saved'))}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
async function requestQR(){const name=$('#customer-name')?.value.trim(),contact=$('#customer-contact')?.value.trim(),address=$('#customer-address')?.value.trim();if(!name||!contact||(state.delivery==='delivery'&&!address)){alert('Please complete the order details. / សូមបំពេញព័ត៌មានបញ្ជាទិញ។');return}const items=state.cart.map(i=>{const p=state.products.find(p=>p.id===i.id);return {name:p.name_en,quantity:i.qty,price:p.price}}),subtotal=items.reduce((n,i)=>n+i.quantity*i.price,0),shipping=state.delivery==='delivery'?Number(String(state.settings.shipping[state.region]).replace('$','')):0;try{const response=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({telegramInitData:window.Telegram?.WebApp?.initData||'',name,contact,address,delivery:state.delivery,region:state.region,items,subtotal,shipping,total:subtotal+shipping})});if(!response.ok)throw Error();state.cart=[];save();alert(t('orderSent'));showShop()}catch{alert(t('serverError'))}}
copy.en.sizes='Sizes';copy.en.selectSize='Select size';copy.en.chooseSize='Please select a size.';copy.en.charms='Charms & dolls';copy.km.sizes='ទំហំ';copy.km.selectSize='ជ្រើសរើសទំហំ';copy.km.chooseSize='សូមជ្រើសរើសទំហំ។';copy.km.charms='គ្រឿងព្យួរ និងតុក្កតា';
function sizePicker(p){const sizes=p.category==='clothes'&&Array.isArray(p.sizes)?p.sizes:[];return sizes.length?`<label class="size-picker">${t('sizes')}<select id="size-${p.id}"><option value="">${t('selectSize')}</option>${sizes.map(size=>`<option value="${size}">${size}</option>`).join('')}</select></label>`:''}
function shop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section><div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products">${list.length?list.map(p=>`<article class="product"><div class="product-image">${image(p)}</div><div class="product-body"><h3 class="product-title">${productName(p)}</h3><p class="description">${description(p)}</p><div class="product-meta"><span>${t(p.category)}</span><span class="product-price">${money(p.price)}</span></div>${sizePicker(p)}<button class="add" onclick="add('${p.id}')">${t('add')}</button></div></article>`).join(''):`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
function cart(){const rows=state.cart.map(i=>{const p=state.products.find(x=>x.id===i.id);if(!p)return '';return `<div class="cart-row"><div class="thumb">${image(p)}</div><div><p>${productName(p)}</p>${i.size?`<small>${t('sizes')}: ${i.size}</small>`:''}<div class="quantity"><button onclick="change('${p.id}','${i.size||''}',-1)">−</button> ${i.qty} <button onclick="change('${p.id}','${i.size||''}',1)">+</button></div></div><div class="right"><b>${money(p.price*i.qty)}</b><br><button class="back" onclick="removeItem('${p.id}','${i.size||''}')">×</button></div></div>`}).join(''),sub=state.cart.reduce((n,i)=>n+(state.products.find(p=>p.id===i.id)?.price||0)*i.qty,0);return `<section class="panel"><button class="back" onclick="showShop()">${t('continue')}</button><h2>${t('yourOrder')}</h2>${rows||`<div class="empty">${t('empty')}</div>`}${state.cart.length?checkout(sub):''}</section>`}
function productAdmin(){return `<div class="admin-grid"><div class="panel"><h2>${t('upload')}</h2><form id="product-form" onsubmit="saveProduct(event)"><div class="form-grid"><label class="field">${t('productEn')}<input name="name_en" required></label><label class="field">${t('productKm')}<input name="name_km"></label></div><div class="form-grid"><label class="field">${t('price')}<input name="price" type="number" step="0.01" min="0" required></label><label class="field">${t('category')}<select name="category" onchange="toggleSizeField(this.value)"><option value="clothes">${t('clothes')}</option><option value="bags">${t('bags')}</option><option value="charms">${t('charms')}</option></select></label></div><label class="field" id="size-field">${t('sizes')} <small>(Clothing only: S, M, L, XL)</small><input name="sizes" placeholder="S, M, L, XL"></label><label class="field">${t('descriptionEn')}<textarea name="description_en"></textarea></label><label class="field">${t('descriptionKm')}<textarea name="description_km"></textarea></label><label class="field">${t('photo')}<input name="photo" type="file" accept="image/png,image/jpeg,image/webp" required></label><div class="checks"><label><input name="published" type="checkbox" checked> ${t('published')}</label><label><input name="featured" type="checkbox"> ${t('featuredItem')}</label></div><button class="primary">${t('save')}</button></form></div><div class="panel"><h2>${t('products')}</h2><div class="admin-products">${state.products.map(p=>`<div class="admin-product"><div class="mini">${image(p)}</div><div><b>${p.name_en}</b><br><small>${money(p.price)} · ${p.category==='clothes'?((p.sizes||[]).join(', ')||'One size'):t(p.category)}</small></div><button class="danger" onclick="deleteProduct('${p.id}')">${t('delete')}</button></div>`).join('')||`<div class="empty">${t('noProducts')}</div>`}</div></div></div>`}
function toggleSizeField(category){const field=$('#size-field');if(!field)return;const show=category==='clothes';field.hidden=!show;if(!show){const input=field.querySelector('input');if(input)input.value=''}}
function add(id){const product=state.products.find(p=>p.id===id),sizes=Array.isArray(product?.sizes)?product.sizes:[],size=$(`#size-${id}`)?.value||'';if(sizes.length&&!size){alert(t('chooseSize'));return}const item=state.cart.find(x=>x.id===id&&(x.size||'')===size);item?item.qty++:state.cart.push({id,size,qty:1});save();render()}
function change(id,size,n){const item=state.cart.find(x=>x.id===id&&(x.size||'')===size);if(!item)return;item.qty+=n;if(item.qty<1)state.cart=state.cart.filter(x=>x!==item);save();render()}function removeItem(id,size){state.cart=state.cart.filter(x=>!(x.id===id&&(x.size||'')===size));save();render()}
async function requestQR(){const name=$('#customer-name')?.value.trim(),contact=$('#customer-contact')?.value.trim(),address=$('#customer-address')?.value.trim();if(!name||!contact||(state.delivery==='delivery'&&!address)){alert('Please complete the order details. / សូមបំពេញព័ត៌មានបញ្ជាទិញ។');return}const items=state.cart.map(i=>{const p=state.products.find(p=>p.id===i.id);return {name:p.name_en,size:i.size||'',quantity:i.qty,price:p.price}}),subtotal=items.reduce((n,i)=>n+i.quantity*i.price,0),shipping=state.delivery==='delivery'?Number(String(state.settings.shipping[state.region]).replace('$','')):0;try{const response=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({telegramInitData:window.Telegram?.WebApp?.initData||'',name,contact,address,delivery:state.delivery,region:state.region,items,subtotal,shipping,total:subtotal+shipping})});if(!response.ok)throw Error();state.cart=[];save();alert(t('orderSent'));showShop()}catch{alert(t('serverError'))}}
