function photoUrls(p){const urls=Array.isArray(p?.image_urls)?p.image_urls.filter(Boolean):[];return urls.length?urls:(p?.image_url?[p.image_url]:[])}
function image(p){const src=photoUrls(p)[0];return src?`<img src="${src}" alt="${p.name_en}">`:`<div class="blank-image">${t(p.category)}</div>`}
function shop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section><div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products">${list.length?list.map(p=>`<article class="product"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}</button><div class="product-body"><h3 class="product-title"><button class="title-button" onclick="showProduct('${p.id}')">${productName(p)}</button></h3><p class="description">${description(p)}</p><div class="product-meta"><span>${t(p.category)}</span><span class="product-price">${money(p.price)}</span></div>${sizePicker(p)}${colorPicker(p)}<button class="detail-link" onclick="showProduct('${p.id}')">${t('viewDetails')}</button><button class="add" onclick="add('${p.id}')">${t('add')}</button></div></article>`).join(''):`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
function productDetail(){const p=state.products.find(x=>x.id===state.productId);if(!p){showShop();return ''}const photos=photoUrls(p);return `<section class="panel product-detail"><button class="back" onclick="showShop()">${t('backToShop')}</button><div class="detail-grid"><div class="gallery">${photos.map(src=>`<img src="${src}" alt="${p.name_en}">`).join('')}</div><div class="detail-info"><span class="category-label">${t(p.category)}</span><h2>${productName(p)}</h2><div class="detail-price">${money(p.price)}</div><p class="detail-description">${description(p)}</p>${sizePicker(p)}${colorPicker(p)}<button class="add" onclick="add('${p.id}')">${t('add')}</button></div></div></section>`}
function render(){$('#app').innerHTML=`<main class="shell">${header()}${state.view==='shop'?shop():state.view==='cart'?cart():state.view==='detail'?productDetail():admin()}<footer class="footer">${t('footer')}</footer></main>`}
function showProduct(id){state.productId=id;state.view='detail';render()}
function productAdmin(){const editing=state.editId?state.products.find(p=>p.id===state.editId):null,category=editing?.category||'clothes';return `<div class="admin-grid"><div class="panel"><h2>${editing?t('editProduct'):t('upload')}</h2><form id="product-form" onsubmit="saveProduct(event)"><div class="form-grid"><label class="field">${t('productEn')}<input name="name_en" required value="${editing?.name_en||''}"></label><label class="field">${t('productKm')}<input name="name_km" value="${editing?.name_km||''}"></label></div><div class="form-grid"><label class="field">${t('price')}<input name="price" type="number" step="0.01" min="0" required value="${editing?.price||''}"></label><label class="field">${t('category')}<select name="category" onchange="toggleSizeField(this.value)"><option value="clothes" ${category==='clothes'?'selected':''}>${t('clothes')}</option><option value="bags" ${category==='bags'?'selected':''}>${t('bags')}</option><option value="charms" ${category==='charms'?'selected':''}>${t('charms')}</option></select></label></div><label class="field" id="size-field" ${category==='clothes'?'':'hidden'}>${t('sizes')} <small>(Clothing only: S, M, L, XL)</small><input name="sizes" placeholder="S, M, L, XL" value="${(editing?.sizes||[]).join(', ')}"></label><label class="field">${t('colors')} <small>(All categories)</small><input name="colors" placeholder="Black, White, Pink" value="${(editing?.colors||[]).join(', ')}"></label><label class="field">${t('descriptionEn')}<textarea name="description_en">${editing?.description_en||''}</textarea></label><label class="field">${t('descriptionKm')}<textarea name="description_km">${editing?.description_km||''}</textarea></label><label class="field">${t('photos')}<input name="photo" type="file" accept="image/png,image/jpeg,image/webp" multiple ${editing?'':'required'}><small>${t('photosHint')}</small></label><div class="checks"><label><input name="published" type="checkbox" ${editing?.published===false?'':'checked'}> ${t('published')}</label><label><input name="featured" type="checkbox" ${editing?.featured?'checked':''}> ${t('featuredItem')}</label></div><button class="primary">${editing?t('update'):t('save')}</button>${editing?`<button class="secondary" type="button" onclick="cancelEdit()">${t('cancel')}</button>`:''}</form></div><div class="panel"><h2>${t('products')}</h2><div class="admin-products">${state.products.map(p=>`<div class="admin-product"><div class="mini">${image(p)}</div><div><b>${p.name_en}</b><br><small>${money(p.price)} · ${photoUrls(p).length} ${t('photos')}</small></div><button class="edit" onclick="beginEdit('${p.id}')">${t('edit')}</button><button class="danger" onclick="deleteProduct('${p.id}')">${t('delete')}</button></div>`).join('')||`<div class="empty">${t('noProducts')}</div>`}</div></div></div>`}
function beginEdit(id){state.editId=id;render()}function cancelEdit(){state.editId=null;render()}
async function saveProduct(event){event.preventDefault();const form=event.currentTarget,files=[...form.photo.files],editing=state.editId?state.products.find(p=>p.id===state.editId):null;if(files.length>3){alert('Choose up to 3 photos.');return}if(!editing&&!files.length){alert('Choose at least 1 photo.');return}const imageDataList=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})));const input=Object.fromEntries(new FormData(form));input.imageDataList=imageDataList;input.published=form.published.checked;input.featured=form.featured.checked;if(editing){input.image_url=editing.image_url;input.image_urls=photoUrls(editing)}try{await adminFetch(editing?`/api/admin/products/${editing.id}`:'/api/admin/products',{method:editing?'PATCH':'POST',body:JSON.stringify(input)});state.editId=null;await loadAdmin();render();alert(t('saved'))}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
const SIZE_OPTIONS=['XS','S','M','L','XL','2XL'];
const COLOR_OPTIONS=[{value:'black',en:'Black',km:'ខ្មៅ',tone:'#242424'},{value:'white',en:'White',km:'ស',tone:'#f8f7f2'},{value:'pink',en:'Pink',km:'ផ្កាឈូក',tone:'#f3b3c4'},{value:'blue',en:'Blue',km:'ខៀវ',tone:'#72aee6'},{value:'brown',en:'Brown',km:'ត្នោត',tone:'#a87551'},{value:'grey',en:'Grey',km:'ប្រផេះ',tone:'#9da1a1'}];
copy.en.mainPhoto='Main photo';copy.en.detailPhoto='Long detail photo';copy.en.photoMainHint='One photo for the home page.';copy.en.photoDetailHint='One long photo shown on the product detail page.';copy.en.chooseSizes='Select available sizes';copy.en.chooseColors='Select available colors';copy.en.color='Color';copy.km.mainPhoto='រូបភាពសំខាន់';copy.km.detailPhoto='រូបភាពលម្អិតវែង';copy.km.photoMainHint='រូបភាពមួយសម្រាប់ទំព័រដើម។';copy.km.photoDetailHint='រូបភាពវែងមួយសម្រាប់ទំព័រព័ត៌មានលម្អិត។';copy.km.chooseSizes='ជ្រើសរើសទំហំដែលមាន';copy.km.chooseColors='ជ្រើសរើសពណ៌ដែលមាន';copy.km.color='ពណ៌';
function colorOption(value){return COLOR_OPTIONS.find(c=>c.value===String(value).toLowerCase())||{value:String(value),en:String(value),km:String(value),tone:'#ddd'}}
function colorName(value){const color=colorOption(value);return state.language==='km'?color.km:color.en}
function variantPicker(p){const sizes=p.category==='clothes'&&Array.isArray(p.sizes)?p.sizes:[],colors=Array.isArray(p.colors)?p.colors:[];return `${sizes.length?`<div class="variant-group"><b>${t('sizes')}</b><div class="variant-options">${sizes.map(size=>`<label class="variant-chip"><input type="radio" name="size-${p.id}" value="${size}"><span>${size}</span></label>`).join('')}</div></div>`:''}${colors.length?`<div class="variant-group"><b>${t('colors')}</b><div class="variant-options">${colors.map(value=>{const color=colorOption(value);return `<label class="variant-chip color-chip"><input type="radio" name="color-${p.id}" value="${color.value}"><span class="swatch" style="background:${color.tone}"></span><span>${colorName(value)}</span></label>`}).join('')}</div></div>`:''}`}
function selectedOption(id,type){return document.querySelector(`input[name="${type}-${id}"]:checked`)?.value||''}
function image(p){return p.image_url?`<img src="${p.image_url}" alt="${p.name_en}">`:`<div class="blank-image">${t(p.category)}</div>`}
function shop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section><div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products">${list.length?list.map(p=>`<article class="product"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}</button><div class="product-body"><h3 class="product-title"><button class="title-button" onclick="showProduct('${p.id}')">${productName(p)}</button></h3><p class="description">${description(p)}</p><div class="product-meta"><span>${t(p.category)}</span><span class="product-price">${money(p.price)}</span></div><button class="add" onclick="showProduct('${p.id}')">${t('viewDetails')}</button></div></article>`).join(''):`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
function productDetail(){const p=state.products.find(x=>x.id===state.productId);if(!p){showShop();return ''}const detailImage=p.detail_image_url||p.image_url;return `<section class="panel product-detail"><button class="back" onclick="showShop()">${t('backToShop')}</button><div class="detail-info"><span class="category-label">${t(p.category)}</span><h2>${productName(p)}</h2><div class="detail-price">${money(p.price)}</div><p class="detail-description">${description(p)}</p>${variantPicker(p)}<button class="add" onclick="add('${p.id}')">${t('add')}</button></div><div class="long-detail-image"><img src="${detailImage}" alt="${p.name_en}"></div></section>`}
function render(){$('#app').innerHTML=`<main class="shell">${header()}${state.view==='shop'?shop():state.view==='cart'?cart():state.view==='detail'?productDetail():admin()}<footer class="footer">${t('footer')}</footer></main>`}
function showProduct(id){state.productId=id;state.view='detail';render()}
function toggleSizeField(category){const field=$('#size-field');if(!field)return;field.hidden=category!=='clothes'}
function checks(name,items,selected,format){return `<div class="admin-choice-grid">${items.map(item=>{const value=typeof item==='string'?item:item.value,label=format?format(item):item;return `<label class="admin-choice"><input type="checkbox" name="${name}" value="${value}" ${selected.includes(value)?'checked':''}><span>${label}</span></label>`}).join('')}</div>`}
function productAdmin(){const editing=state.editId?state.products.find(p=>p.id===state.editId):null,category=editing?.category||'clothes',sizes=editing?.sizes||[],colors=editing?.colors||[];return `<div class="admin-grid"><div class="panel"><h2>${editing?t('editProduct'):t('upload')}</h2><form id="product-form" onsubmit="saveProduct(event)"><div class="form-grid"><label class="field">${t('productEn')}<input name="name_en" required value="${editing?.name_en||''}"></label><label class="field">${t('productKm')}<input name="name_km" value="${editing?.name_km||''}"></label></div><div class="form-grid"><label class="field">${t('price')}<input name="price" type="number" step="0.01" min="0" required value="${editing?.price||''}"></label><label class="field">${t('category')}<select name="category" onchange="toggleSizeField(this.value)"><option value="clothes" ${category==='clothes'?'selected':''}>${t('clothes')}</option><option value="bags" ${category==='bags'?'selected':''}>${t('bags')}</option><option value="charms" ${category==='charms'?'selected':''}>${t('charms')}</option></select></label></div><div id="size-field" ${category==='clothes'?'':'hidden'}><label class="field">${t('chooseSizes')}</label>${checks('sizes',SIZE_OPTIONS,sizes)}</div><label class="field">${t('chooseColors')}</label>${checks('colors',COLOR_OPTIONS,colors,color=>`${color.en} / ${color.km}`)}<label class="field">${t('descriptionEn')}<textarea name="description_en">${editing?.description_en||''}</textarea></label><label class="field">${t('descriptionKm')}<textarea name="description_km">${editing?.description_km||''}</textarea></label><label class="field">${t('mainPhoto')}<input name="main_photo" type="file" accept="image/png,image/jpeg,image/webp" ${editing?'':'required'}><small>${t('photoMainHint')}</small></label><label class="field">${t('detailPhoto')}<input name="detail_photo" type="file" accept="image/png,image/jpeg,image/webp" ${editing?'':'required'}><small>${t('photoDetailHint')}</small></label><div class="checks"><label><input name="published" type="checkbox" ${editing?.published===false?'':'checked'}> ${t('published')}</label><label><input name="featured" type="checkbox" ${editing?.featured?'checked':''}> ${t('featuredItem')}</label></div><button class="primary">${editing?t('update'):t('save')}</button>${editing?`<button class="secondary" type="button" onclick="cancelEdit()">${t('cancel')}</button>`:''}</form></div><div class="panel"><h2>${t('products')}</h2><div class="admin-products">${state.products.map(p=>`<div class="admin-product"><div class="mini">${image(p)}</div><div><b>${p.name_en}</b><br><small>${money(p.price)} · ${t(p.category)}</small></div><button class="edit" onclick="beginEdit('${p.id}')">${t('edit')}</button><button class="danger" onclick="deleteProduct('${p.id}')">${t('delete')}</button></div>`).join('')||`<div class="empty">${t('noProducts')}</div>`}</div></div></div>`}
function beginEdit(id){state.editId=id;render()}function cancelEdit(){state.editId=null;render()}
async function toData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function saveProduct(event){event.preventDefault();const form=event.currentTarget,editing=state.editId?state.products.find(p=>p.id===state.editId):null,main=form.main_photo.files[0],detail=form.detail_photo.files[0];if(!editing&&(!main||!detail)){alert('Choose both a main photo and a detail photo.');return}const input=Object.fromEntries(new FormData(form));input.sizes=[...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value);input.colors=[...form.querySelectorAll('input[name="colors"]:checked')].map(x=>x.value);input.mainImageData=main?await toData(main):'';input.detailImageData=detail?await toData(detail):'';input.published=form.published.checked;input.featured=form.featured.checked;if(editing){input.image_url=editing.image_url;input.detail_image_url=editing.detail_image_url||''}try{await adminFetch(editing?`/api/admin/products/${editing.id}`:'/api/admin/products',{method:editing?'PATCH':'POST',body:JSON.stringify(input)});state.editId=null;await loadAdmin();render();alert(t('saved'))}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
function add(id){const product=state.products.find(p=>p.id===id),sizes=product?.category==='clothes'&&Array.isArray(product?.sizes)?product.sizes:[],colors=Array.isArray(product?.colors)?product.colors:[],size=selectedOption(id,'size'),color=selectedOption(id,'color');if(sizes.length&&!size){alert(t('chooseSize'));return}if(colors.length&&!color){alert(t('chooseColor'));return}const item=state.cart.find(x=>x.id===id&&(x.size||'')===size&&(x.color||'')===color);item?item.qty++:state.cart.push({id,size,color,qty:1});save();render()}

copy.en.paymentQr='Payment QR';copy.en.scanToPay='Scan this QR code to pay. Please keep your order number.';copy.en.orderNumber='Order number';
copy.km.paymentQr='QR កូដបង់ប្រាក់';copy.km.scanToPay='ស្កេន QR កូដនេះដើម្បីបង់ប្រាក់។ សូមរក្សាលេខបញ្ជាទិញរបស់អ្នក។';copy.km.orderNumber='លេខបញ្ជាទិញ';
function paymentPage(){const payment=state.paymentOrder;if(!payment){showShop();return ''}return `<section class="panel payment-page"><button class="back" onclick="showShop()">${t('continue')}</button><h2>${t('paymentQr')}</h2><p><b>${t('orderNumber')}:</b> ${payment.order_number}</p><img class="payment-qr" src="${payment.qr}" alt="${t('paymentQr')}"><p class="payment-note">${t('scanToPay')}</p></section>`}
function render(){$('#app').innerHTML=`<main class="shell">${header()}${state.view==='shop'?shop():state.view==='cart'?cart():state.view==='detail'?productDetail():state.view==='payment'?paymentPage():admin()}<footer class="footer">${t('footer')}</footer></main>`}
async function requestQR(){
  const name=$('#customer-name')?.value.trim(),contact=$('#customer-contact')?.value.trim(),address=$('#customer-address')?.value.trim();
  if(!name||!contact||(state.delivery==='delivery'&&!address)){alert('Please complete the order details. / សូមបំពេញព័ត៌មានបញ្ជាទិញ។');return}
  const items=state.cart.map(i=>{const p=state.products.find(p=>p.id===i.id);return {name:p.name_en,size:i.size||'',color:i.color||'',quantity:i.qty,price:p.price}});
  const subtotal=items.reduce((n,i)=>n+i.quantity*i.price,0),shipping=state.delivery==='delivery'?Number(String(state.settings.shipping[state.region]).replace('$','')):0;
  try{
    const response=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({telegramInitData:window.Telegram?.WebApp?.initData||'',name,contact,address,delivery:state.delivery,region:state.region,items,subtotal,shipping,total:subtotal+shipping})});
    const result=await response.json().catch(()=>({}));
    if(!response.ok)throw Error(result.error||'Order request failed');
    state.cart=[];save();
    if(result.payment_qr_url){state.paymentOrder={order_number:result.order_number,qr:result.payment_qr_url};state.view='payment';render();return}
    alert(t('orderSent'));showShop();
  }catch(error){alert(error.message||t('serverError'))}
}

function variantKey(id,type){return `${type}:${id}`}
function chooseOption(id,type,value){state.selectedVariants=state.selectedVariants||{};state.selectedVariants[variantKey(id,type)]=value;render()}
function selectedOption(id,type){return state.selectedVariants?.[variantKey(id,type)]||''}
function variantPicker(p){
  const sizes=p.category==='clothes'&&Array.isArray(p.sizes)?p.sizes:[],colors=Array.isArray(p.colors)?p.colors:[];
  const size=selectedOption(p.id,'size'),color=selectedOption(p.id,'color');
  return `${sizes.length?`<div class="variant-group"><b>${t('sizes')}</b><div class="variant-options">${sizes.map(value=>`<button type="button" class="variant-chip ${size===value?'selected':''}" onclick="chooseOption('${p.id}','size','${value}')">${value}</button>`).join('')}</div></div>`:''}${colors.length?`<div class="variant-group"><b>${t('colors')}</b><div class="variant-options">${colors.map(value=>{const option=colorOption(value);return `<button type="button" class="variant-chip color-chip ${color===option.value?'selected':''}" onclick="chooseOption('${p.id}','color','${option.value}')"><span class="swatch" style="background:${option.tone}"></span><span>${colorName(value)}</span></button>`}).join('')}</div></div>`:''}`
}
copy.en.addedToBag='Added to bag ✓';copy.km.addedToBag='បានបន្ថែមទៅកាបូប ✓';
function showAddedMessage(){document.querySelector('.added-message')?.remove();const message=document.createElement('div');message.className='added-message';message.textContent=t('addedToBag');document.body.append(message);setTimeout(()=>message.remove(),2200)}
function add(id){const product=state.products.find(p=>p.id===id),sizes=product?.category==='clothes'&&Array.isArray(product?.sizes)?product.sizes:[],colors=Array.isArray(product?.colors)?product.colors:[],size=selectedOption(id,'size'),color=selectedOption(id,'color');if(sizes.length&&!size){alert(t('chooseSize'));return}if(colors.length&&!color){alert(t('chooseColor'));return}const item=state.cart.find(x=>x.id===id&&(x.size||'')===size&&(x.color||'')===color);item?item.qty++:state.cart.push({id,size,color,qty:1});save();render();showAddedMessage()}
