copy.km.proofAlerts='ការជូនដំណឹងរូបភាពបង់ប្រាក់';copy.km.proofAlertsHint='ភ្ជាប់គណនី Telegram នេះ ដើម្បីទទួលរូបភាពបញ្ជាក់ការបង់ប្រាក់ដែលផ្ញើទៅ Bot។';copy.km.connectTelegram='ភ្ជាប់គណនី Telegram នេះ';
function settingsAdmin(){const fees=Object.entries(state.settings.shipping||{}).map(([k,v])=>`<div class="settings-row"><span>${k}</span><label>$ <input name="fee-${k}" value="${String(v).replace('$','')}"></label></div>`).join('');return `<div class="panel"><h2>${t('homeTitle')}</h2><form id="settings-form" onsubmit="saveSettings(event)"><label class="field">English headline<input name="hero_en" value="${state.settings.hero_en||''}"></label><label class="field">Khmer headline<input name="hero_km" value="${state.settings.hero_km||''}"></label><label class="field">English introduction<textarea name="hero_text_en">${state.settings.hero_text_en||''}</textarea></label><label class="field">Khmer introduction<textarea name="hero_text_km">${state.settings.hero_text_km||''}</textarea></label><label class="field">${t('pickupAddress')}<input name="pickup" value="${state.settings.pickup||''}"></label><h3>${t('shippingFees')}</h3>${fees}<button class="primary">${t('save')}</button></form></div><div class="panel"><h2>${t('proofAlerts')}</h2><p class="description">${t('proofAlertsHint')}</p><button type="button" class="primary" onclick="connectTelegramOwner()">${t('connectTelegram')}</button></div>`}
async function connectTelegramOwner(){try{const telegramInitData=window.Telegram?.WebApp?.initData||'';const result=await adminFetch('/api/admin/telegram-owner',{method:'POST',body:JSON.stringify({telegramInitData})});alert(result.message)}catch(error){alert(error.message)}}
async function adminTab(tab){const hasKey=Boolean(key());state.adminTab=tab;render();if(!hasKey){alert('Enter the admin key, then tap this tab again.');return}await loadAdmin();render()}
copy.en.myOrders='My orders';copy.en.orderHistory='My orders';copy.en.noOrders='You have no orders yet.';copy.en.openInTelegram='Open the store inside Telegram to view your orders.';copy.en.status_awaiting_payment='Waiting for payment';copy.en.status_paid='Payment confirmed';copy.en.status_shipping='On the way';copy.en.status_ready_for_pickup='Ready for pickup';copy.en.status_completed='Completed';copy.en.status_cancelled='Cancelled';
copy.km.myOrders='ការបញ្ជាទិញខ្ញុំ';copy.km.orderHistory='ការបញ្ជាទិញរបស់ខ្ញុំ';copy.km.noOrders='អ្នកមិនទាន់មានការបញ្ជាទិញទេ។';copy.km.openInTelegram='សូមបើកហាងក្នុង Telegram ដើម្បីមើលការបញ្ជាទិញ។';copy.km.status_awaiting_payment='រង់ចាំការបង់ប្រាក់';copy.km.status_paid='បានបញ្ជាក់ការបង់ប្រាក់';copy.km.status_shipping='កំពុងដឹកជញ្ជូន';copy.km.status_ready_for_pickup='រួចរាល់សម្រាប់មកយក';copy.km.status_completed='បានបញ្ចប់';copy.km.status_cancelled='បានលុបចោល';
function header(){return `<header class="topbar"><div class="brand">CYPRESS<span>Fashion Store</span></div><div class="top-actions"><button class="pill" onclick="setLanguage()">${state.language==='en'?'ខ្មែរ':'EN'}</button><button class="pill ${state.view==='shop'?'active':''}" onclick="showShop()">${t('shop')}</button><button class="pill ${state.view==='my-orders'?'active':''}" onclick="showMyOrders()">${t('myOrders')}</button><button class="pill ${state.view==='admin'?'active':''}" onclick="showAdmin()">${t('admin')}</button></div></header>`}
function myOrdersPage(){const orders=Array.isArray(state.myOrders)?state.myOrders:[];if(state.myOrdersLoading)return `<section class="panel"><h2>${t('orderHistory')}</h2><div class="empty">Loading…</div></section>`;if(state.myOrdersError)return `<section class="panel"><h2>${t('orderHistory')}</h2><div class="empty">${state.myOrdersError}</div></section>`;return `<section class="panel customer-orders"><h2>${t('orderHistory')}</h2>${orders.length?orders.map(order=>{const items=Array.isArray(order.items)?order.items:[];return `<article class="customer-order"><div><b>${order.order_number}</b><br><small>${new Date(order.created_at).toLocaleString()}</small></div><span class="order-status status-${order.status}">${t(`status_${order.status}`)}</span><div class="customer-order-items">${items.map(item=>`<div>${item.quantity} × ${item.name}${item.size?` · ${item.size}`:''}${item.color?` · ${colorName(item.color)}`:''}</div>`).join('')}</div><strong>${money(order.total)}</strong></article>`}).join(''):`<div class="empty">${t('noOrders')}</div>`}</section>`}
function render(){$('#app').innerHTML=`<main class="shell">${header()}${state.view==='shop'?shop():state.view==='cart'?cart():state.view==='detail'?productDetail():state.view==='payment'?paymentPage():state.view==='my-orders'?myOrdersPage():admin()}<footer class="footer">${t('footer')}</footer></main>`}
async function showMyOrders(){state.view='my-orders';state.myOrdersLoading=true;state.myOrdersError='';render();try{const response=await fetch('/api/my-orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({telegramInitData:window.Telegram?.WebApp?.initData||''})});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||t('openInTelegram'));state.myOrders=Array.isArray(data.orders)?data.orders:[]}catch(error){state.myOrders=[];state.myOrdersError=error.message||t('openInTelegram')}finally{state.myOrdersLoading=false;render()}}
